export function OpeningHours({
  heading = "{{heading}}",
  todayHours = "{{todayHours}}",
  openNow = {{openNow}},
  accent = "{{accent}}",
}) {
  const rows = [
    ["Tue", "9:00 - 18:00"],
    ["Wed", "9:00 - 18:00"],
    ["Sat", "10:00 - 14:00"],
    ["Sun", "Closed"],
  ];
  return (
    <div style={{ font: "14px system-ui, sans-serif", color: "#241430", maxWidth: 280, padding: 18,
      border: "1px solid #24143022", borderRadius: 14, background: "#FAF7F2" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>{heading}</h3>
        <span style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.04em",
          padding: "4px 9px", borderRadius: 999, background: accent, color: "#241430" }}>{openNow ? "Open now" : "Closed now"}</span>
      </div>
      <dl style={{ margin: 0 }}>
        <div style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: "1px solid #24143012", fontWeight: 700 }}>
          <dt>Today</dt><dd style={{ margin: 0 }}>{todayHours}</dd>
        </div>
        {rows.map(([day, time]) => (
          <div key={day} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: "1px solid #24143012" }}>
            <dt style={{ fontWeight: 600 }}>{day}</dt><dd style={{ margin: 0, color: "#241430cc" }}>{time}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}
